/* kleiner test */#define void     int#define line(x)  draw_line(clip(plus_origin(x)),0)extern void draw_line();extern int *plus_origin();extern int *clip();extern int bs_on();extern int bs_out();extern int linest();extern int draw0();main(){	open_grad();	bs_out();	cleargraf();	draw0(3);	zeichne();	bs_on();}void zeichne(){	int liste[4];	int i;	for (i=-550;i<500;i+=3)	{		liste[0]=-800;		liste[1]=i+400;		liste[2]=800;		liste[3]=i-400;		draw0(i);		line(liste);	}}